    public static BrandEditorialContent Find(string slug) =>
        Content.TryGetValue(slug, out BrandEditorialContent? content)
            ? Editorial.TryGetValue(slug, out var editorial)
                ? content with
                {
                    Introduction = editorial.Introduction,
                    Specialization = editorial.Specialization,
                    ShoppingAdvice = editorial.ShoppingAdvice
                }
                : content
            : Empty;

    private static BrandEditorialContent Entry(
        string[] productFamilies,
        string[] strengths,
        string audience) =>
        new(productFamilies, strengths, audience);
}

